    C c;
    constructor(C _c) { c = _c; }

    // We accept a receiver and amount; the test contract is the deployer/owner of c
    function run(address receiver, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // record balance of c before the call
        uint256 before = address(c).balance;

        bool reverted;
        // try to invoke sendTo with provided parameters, capturing revert status
        try c.sendTo{value: 0}(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;
        // If call reverted, balances must be unchanged. If call did not revert, then:
        // - receiver must be non-zero
        // - amount must be > 0
