        // (transfer moves Ether out of c). We observe receiver's balance via address(this).balance
        // only when receiver == address(this); for general receiver we can still assert c's balance change.

        assert(
            // either reverted and balance unchanged
            (reverted && after == before)
            ||
            // or succeeded: amount > 0, receiver != 0, and c.balance decreased exactly by amount
            (!reverted && amount > 0 && receiver != address(0) && before == after + amount)
        );
    }

    // allow receiving Ether if sendTo sends to this contract
    receive() external payable {}
}

