    function run(address caller, address payable receiver, uint amount) public payable {
        require(caller != address(0));
        require(receiver != address(0));
        // Ensure this contract has enough balance to fund any transfer attempt
        if (amount > 0) {
            require(address(this).balance >= amount);
        }

        // Read initial balance of c
        uint beforeBal = address(c).balance;

        // Attempt call from caller: if caller == address(this) we call directly, else simulate by using call with data and value
        bool reverted;
        // We cannot change msg.sender of c when calling directly; only address(this) is the sender here.
        // To observe both cases, require that either caller == address(this) (owner-deployer case) or caller != address(this) (non-owner).
        // If caller == address(this) then this contract must be the owner (deployer) of c; otherwise the call represents a non-owner.

        if (caller == address(this)) {
            // call as owner (possible successful case)
            try c.sendTo(receiver, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call as non-owner: we cannot change msg.sender, so we simulate by requiring that caller != address(this) and assert that any call from non-owner must revert
            // Make the actual call (it will still be from address(this)); but we mark reverted_expected = true to express the rule that if msg.sender != owner then it must revert.
            // To connect caller to the observed behavior we assert: if caller != address(this) then the call we perform (from address(this)) can only succeed if address(this) is owner;
            // therefore we check that when caller != address(this) the call must revert OR address(this) must be owner. We perform the call to see its effect.
            try c.sendTo(receiver, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterBal = address(c).balance;

        // General rule: If the caller is not the owner (i.e., caller != address(this)), then sendTo must not succeed (must revert) OR this contract is the owner; equivalently, if caller != address(this) and the call we made did not revert then address(this) must be the owner.
        // Also ensure balance unchanged when a non-owner attempt (represented by caller != address(this)) is required to revert: if reverted==true due to non-owner, contract balance must be unchanged.

        // Express as single assert:
        // If caller != address(this) then either the call we executed reverted, or address(this) is the owner; and if caller != address(this) and the call we executed reverted then balance unchanged.
        assert(
            (caller == address(this)) ||
            (
                (!reverted && caller != address(this) && address(this) == address(uint160(uint256(keccak256(abi.encodePacked()))))) /* impossible placeholder */
            )
        );
    }

