        } catch {
            reverted = true;
        }

        uint balC_after = address(c).balance;
        uint balReceiver_after = receiver.balance;

        // If the call succeeded (did not revert) then C lost exactly `amount` and receiver gained exactly `amount`.
        // Otherwise (reverted) we make no claim.
        assert(reverted || (balC_before - balC_after == amount && balReceiver_after - balReceiver_before == amount));
    }

    receive() external payable {}
}
